// SPEC §9.2 — the fingerprint, computed on the client, deterministic.
//
// This must produce byte-for-byte what backend/internal/identity/internal/
// match computes from the same raw signals: the server keys aliases on its
// own recomputation, but a reporter that disagrees would make the
// identityMap it receives useless. test/fingerprint.test.ts pins vectors
// generated by the Go implementation.

import { createHash } from "node:crypto";

export interface Signals {
  framework: string;
  filePath: string;
  titlePath: string[];
  paramSignature: string;
}

export const FINGERPRINT_VERSION = "fp1:";

// U+0000 between titlePath elements — never a space, never "" (N22).
// Built from the code point rather than written as an escape: N22 records
// two pipelines that turned the escape into something else, and the sed
// that edited this very line did it a third time.
export const TITLE_SEP = String.fromCharCode(0);

/** Forward slashes, no leading "./", lower-case extension, repo root stripped. */
export function normalizeFilePath(p: string, repoRoot?: string): string {
  let out = p.replace(/\\/g, "/");
  if (repoRoot) {
    const root = repoRoot.replace(/\\/g, "/").replace(/\/+$/, "") + "/";
    if (out.startsWith(root)) out = out.slice(root.length);
  }
  if (out.startsWith("./")) out = out.slice(2);
  const dot = out.lastIndexOf(".");
  const slash = out.lastIndexOf("/");
  if (dot > slash && dot >= 0) out = out.slice(0, dot) + out.slice(dot).toLowerCase();
  return out;
}

/** Trim and collapse whitespace runs to one space. */
export function normalizeTitle(t: string): string {
  return t.trim().split(/\s+/).filter((s) => s.length > 0).join(" ");
}

/** key=value pairs sorted by key, joined with "&"; "" when not parameterised. */
export function normalizeParams(params: Record<string, string>): string {
  return Object.keys(params)
    .sort()
    .map((k) => `${k}=${params[k]}`)
    .join("&");
}

export function normalize(s: Signals, repoRoot?: string): Signals {
  return {
    framework: s.framework.trim().toLowerCase(),
    filePath: normalizeFilePath(s.filePath, repoRoot),
    titlePath: s.titlePath.map(normalizeTitle),
    paramSignature: s.paramSignature.trim(),
  };
}

export function fingerprint(s: Signals, repoRoot?: string): string {
  const n = normalize(s, repoRoot);
  const h = createHash("sha256");
  h.update(n.framework);
  h.update("\n");
  h.update(n.filePath);
  h.update("\n");
  h.update(n.titlePath.join(TITLE_SEP));
  h.update("\n");
  h.update(n.paramSignature);
  return FINGERPRINT_VERSION + h.digest("hex");
}

/** "ct_" + first 16 digest bytes as hex (§9.2). */
export function clientTestId(s: Signals, repoRoot?: string): string {
  return "ct_" + fingerprint(s, repoRoot).slice(FINGERPRINT_VERSION.length, FINGERPRINT_VERSION.length + 32);
}
